const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/webhooks/hooks/123/deliveries',
  qs: {
    'filter[status]': 'SOME_STRING_VALUE',
    'filter[resource_name]': 'SOME_STRING_VALUE',
    'filter[event_type]': 'SOME_STRING_VALUE',
    'filter[start]': '2023-01-01',
    'filter[end]': '2023-12-31',
    'filter[contain_resource_id]': '300',
    sort: '-timestamp',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/webhooks/hooks/123/deliveries?filter%5Bstatus%5D=SOME_STRING_VALUE&filter%5Bresource_name%5D=SOME_STRING_VALUE&filter%5Bevent_type%5D=SOME_STRING_VALUE&filter%5Bstart%5D=2023-01-01&filter%5Bend%5D=2023-12-31&filter%5Bcontain_resource_id%5D=300&sort=-timestamp&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

